using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using Newtonsoft.Json;
public static class DodgeV057Checkpoint{
 public static object Read(){var scenes=Enumerable.Range(0,SceneManager.sceneCount).Select(i=>SceneManager.GetSceneAt(i)).Select(s=>new{s.path,s.isDirty,s.isLoaded}).ToArray();var result=new{utc=DateTime.UtcNow.ToString("O"),playing=EditorApplication.isPlaying,paused=EditorApplication.isPaused,compiling=EditorApplication.isCompiling,scene=SceneManager.GetActiveScene().path,scenes,nativeKeyboard=Keyboard.current?.native,keyboardEnabled=Keyboard.current?.enabled,nativeMouse=Mouse.current?.native,mouseEnabled=Mouse.current?.enabled,devices=InputSystem.devices.Select(d=>new{d.name,d.native,d.enabled}).ToArray(),width=Screen.width,height=Screen.height};Directory.CreateDirectory("검증/dodge-v057");File.WriteAllText("검증/dodge-v057/checkpoint.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
 public static object Prepare(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Busy editor; preserve current play");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene; stop before writes");return Read();}
 public static object OpenDungeon(){Prepare();UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/DungeonTest.unity");return Read();}
 public static object RestoreTown(){Prepare();UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Town.unity");return Read();}
}
